    D3DXVECTOR3 dxT0(t0.X, t0.Y, t0.Z);
    D3DXVECTOR3 dxP1(p1.X, p1.Y, p1.Z);
    D3DXVECTOR3 dxT1(t1.X, t1.Y, t1.Z);
