// Behaviour test for 0x00A5A8A0 _STL::__partial_sort<float*, float, less<float> >
#include <cstdio>
#include <cstddef>

namespace _STL {
template <class T> struct less {
    bool operator()(const T& x, const T& y) const { return x < y; }
